"""Camera-guided controller for this single live episode. No resets or simulator access.
Commands are recorded in actions.npy and journal.jsonl alongside camera observations.
"""
import json, sys, pathlib, traceback
import numpy as np
from scipy.spatial.transform import Rotation
from rcb_client import Robot
ROOT=pathlib.Path('/app/runs')
BASE=np.array([2.65,-2.175,.97])
RBASE=np.array([[0.,-1,0],[1,0,0],[0,0,1]])

def world_to_base(p): return RBASE.T@(np.asarray(p)-BASE)
def base_to_world(p): return RBASE@np.asarray(p)+BASE

def unproject(meta,depth,cam,u,v):
    c=meta['cameras'][cam]; K=np.array(c['intrinsic_cv']); M=np.array(c['cam2world_gl'])
    D=depth[-1] if depth.ndim==3 else depth
    z=float(D[int(v),int(u)])
    q=np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z])
    return M[:3,:3]@q+M[:3,3]

def montage(out):
    from PIL import Image,ImageDraw
    files=list((out/'last').glob('*.jpg')); im=Image.new('RGB',(960,280*((len(files)+2)//3))); d=ImageDraw.Draw(im)
    for i,f in enumerate(files):
        x=i%3*320;y=i//3*280;im.paste(Image.open(f),(x,y+25));d.text((x,y+5),f.stem,fill='white')
    im.save(out/'montage.jpg')

class Controller:
    def __init__(self):
        self.r=Robot(); self.spec=self.r.spec(); self.n=1; self.all_actions=[]
        self.obs=self.r.get_obs(video='none',include_depth=True)
        self.record(self.obs,'start')
    def record(self,o,note):
        out=ROOT/f'{self.n:03d}';self.n+=1;o.save(str(out));montage(out);self.obs=o
        p=dict(zip(o.meta['proprio']['layout'],o.meta['proprio']['now']))
        self.cmd=np.array([p['cmd_'+k] for k in self.spec['action_types']['ee_pose']['layout']])
        with open('/app/output/journal.jsonl','a') as f: f.write(json.dumps({'note':note,'path':str(out),'steps':o.meta['control_steps'],'command':self.cmd.tolist()})+'\n')
        print(json.dumps({'path':str(out),'time_left_s':o.meta['time_left_s'],'steps':o.meta['control_steps'],'eef_right':[p['eef_right_'+a] for a in 'xyz'],'eef_left':[p['eef_left_'+a] for a in 'xyz'],'command':self.cmd.tolist()}),flush=True)
    def run(self,c):
        if c['op']=='observe':
            self.record(self.r.get_obs(cameras=c.get('cameras'),seconds=c.get('seconds',0),video='none',include_depth=True),'observe');return
        if c['op']=='point':
            cam=c['camera'];print(unproject(self.obs.meta,self.obs.depth[cam],cam,*c['pixel']).tolist(),flush=True);return
        if c['op']=='state':
            print(json.dumps(dict(zip(self.obs.meta['proprio']['layout'],self.obs.meta['proprio']['now']))),flush=True);return
        if c['op']=='move':
            target=self.cmd.copy()
            for side,off,h in [('right',0,12),('left',6,18)]:
                if side in c:
                    q=c[side]
                    if 'position' in q: target[off:off+3]=world_to_base(q['position']) if q.get('frame','world')=='world' else q['position']
                    if 'rotation' in q: target[off+3:off+6]=q['rotation']
                    if 'matrix_world' in q: target[off+3:off+6]=Rotation.from_matrix(RBASE.T@np.array(q['matrix_world'])).as_rotvec()
                    if 'hand' in q: target[h:h+6]=q['hand']
            n=max(1,int(c.get('seconds',2)/self.spec['control_dt']))
            a=np.linspace(self.cmd,target,n+1)[1:]
            hold=int(c.get('hold',.5)/self.spec['control_dt'])
            if hold:a=np.vstack([a,np.tile(target,(hold,1))])
            if len(a)>200:raise ValueError('chunk exceeds 10 s')
            self.all_actions.extend(a.tolist());np.save('/app/output/actions.npy',np.array(self.all_actions))
            self.record(self.r.submit('ee_pose',a,cameras=c.get('cameras'),include_depth=True,video=c.get('video','none'),note=c.get('note','move')),c.get('note','move'));return
        raise ValueError('unknown op')
if __name__=='__main__':
    ctrl=Controller()
    for line in sys.stdin:
        try: ctrl.run(json.loads(line))
        except Exception:traceback.print_exc();sys.stdout.flush()
